    }

    /** The tables a sheet keeps rows in, each after the tables it refers to. */
    private List<Table> tables() {
        List<Table> found = tables;
        if (found == null) {
            try (Connection connection = dataSource.getConnection()) {
                found = discover(connection.getMetaData());
            } catch (SQLException e) {
                throw new IllegalStateException("The schema could not be read", e);
            }
            tables = found;
        }
        return found;
    }

    private static List<Table> discover(DatabaseMetaData meta) throws SQLException {
        Map<String, List<String>> columns = new LinkedHashMap<>();
        // The columns that may be null, as TABLE.COLUMN.
        Set<String> nullable = new LinkedHashSet<>();
        try (ResultSet rs = meta.getTables(null, "PUBLIC", "%", new String[] { "TABLE", "BASE TABLE" })) {
            while (rs.next()) {
                String name = rs.getString("TABLE_NAME").toUpperCase(Locale.ROOT);
                if (!NOT_KEPT.contains(name)) {
                    columns.put(name, new ArrayList<>());
                }
            }
        }
        for (Map.Entry<String, List<String>> e : columns.entrySet()) {
            try (ResultSet rs = meta.getColumns(null, "PUBLIC", e.getKey(), "%")) {
                while (rs.next()) {
                    if (!"YES".equalsIgnoreCase(rs.getString("IS_GENERATEDCOLUMN"))) {
                        e.getValue().add(rs.getString("COLUMN_NAME").toUpperCase(Locale.ROOT));
                    }
                    if ("YES".equalsIgnoreCase(rs.getString("IS_NULLABLE"))) {
                        nullable.add(e.getKey() + "." + rs.getString("COLUMN_NAME").toUpperCase(Locale.ROOT));
                    }
                }
            }
        }
        Map<String, List<String>> keys = new HashMap<>();
        for (String name : columns.keySet()) {
            List<String> key = new ArrayList<>();
            try (ResultSet rs = meta.getPrimaryKeys(null, "PUBLIC", name)) {
                while (rs.next()) {
                    key.add(rs.getString("COLUMN_NAME").toUpperCase(Locale.ROOT));
                }
            }
            keys.put(name, key);
        }
        // Each table's references to other tables: its column -> the table referred to.
        Map<String, Map<String, String>> refs = new HashMap<>();
        for (String name : columns.keySet()) {
            Map<String, String> to = new LinkedHashMap<>();
            try (ResultSet rs = meta.getImportedKeys(null, "PUBLIC", name)) {
                while (rs.next()) {
                    to.put(rs.getString("FKCOLUMN_NAME").toUpperCase(Locale.ROOT),
                            rs.getString("PKTABLE_NAME").toUpperCase(Locale.ROOT));
                }
            }
            refs.put(name, to);
        }
        Map<String, String> where = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> e : columns.entrySet()) {
            String name = e.getKey();
            if (name.equals(SHEET)) {
                where.put(name, "id = ?");
            } else if (e.getValue().contains("SHEET_ID")) {
                where.put(name, "sheet_id = ?");
            } else {
                // Through a reference to a table carrying the sheet's id: one that is never null, when there is one,
                // so that every row is reached.
                Map.Entry<String, String> through = null;
                for (Map.Entry<String, String> ref : refs.get(name).entrySet()) {
                    List<String> parent = columns.get(ref.getValue());
                    if (parent != null && parent.contains("SHEET_ID")) {
                        if (through == null || (nullable.contains(name + "." + through.getKey())
                                && !nullable.contains(name + "." + ref.getKey()))) {
                            through = ref;
                        }
                    }
                }
                if (through != null) {
                    where.put(name, through.getKey() + " IN (SELECT id FROM " + through.getValue() + " WHERE sheet_id = ?)");
                }
            }
        }
        // Parents before the tables referring to them.
        Set<String> ordered = new LinkedHashSet<>();
        while (ordered.size() < where.size()) {
            int before = ordered.size();
            for (String name : where.keySet()) {
                if (!ordered.contains(name) && refs.get(name).values().stream()
                        .allMatch(p -> p.equals(name) || ordered.contains(p) || !where.containsKey(p))) {
                    ordered.add(name);
                }
            }
            if (ordered.size() == before) {
                throw new IllegalStateException("The sheet's tables refer to each other in a cycle");
            }
        }
        return ordered.stream().map(n -> new Table(n, columns.get(n), where.get(n), keys.get(n))).toList();
    }

    private static byte[] serialize(Object rows) {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(rows);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return bytes.toByteArray();
    }

    @SuppressWarnings("unchecked")
    private static Map<String, List<Map<String, Object>>> deserialize(byte[] data) {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (Map<String, List<Map<String, Object>>>) in.readObject();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } catch (ClassNotFoundException e) {
            throw new IllegalStateException(e);
        }
    }
}
package net.officefloor.hq.app.role;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the delegations of the steward role on a sheet. While the sheet's today is inside a delegation's range, its
 * user acts as a steward, on behalf of the steward who delegated.
 */
@Service
public class DelegationService {

    private final DelegationRepository delegations;
    private final RoleRepository roles;
    private final SheetRepository sheets;
    private final Audit audit;

    public DelegationService(DelegationRepository delegations, RoleRepository roles, SheetRepository sheets,
            Audit audit) {
        this.delegations = delegations;
        this.roles = roles;
        this.sheets = sheets;
        this.audit = audit;
    }

    public List<Delegation> list(String sheetId) {
        return delegations.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Whether the user holds the steward role itself, not by delegation. */
    private boolean isSteward(String sheetId, String user) {
        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK) == Role.STEWARD;
    }

    /**
     * The steward on whose behalf the user acts as a steward on the sheet's today: the one who delegated last of the
     * delegations covering it; empty when none covers it, or when the user is a steward in their own right.
     */
    @Transactional(readOnly = true)
    public Optional<String> delegatorOf(String sheetId, String user) {
        Optional<LocalDate> today = sheets.findById(sheetId).map(Sheet::getToday);
        if (today.isEmpty() || isSteward(sheetId, user)) {
            return Optional.empty();
        }
        return delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, user).stream()
                .filter(d -> d.covers(today.get())).map(Delegation::getDelegatedBy).findFirst();
    }

    /** A steward delegates the steward role to the user from the from-date (blank: the sheet's today) to the to-date. */
    @Transactional
    public Delegation delegate(String sheetId, String by, String user, LocalDate from, LocalDate to) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
        if (!isSteward(sheetId, by)) {
            throw new DelegationForbiddenException(sheetId, by);
        }
        LocalDate fromDate = from == null ? sheet.getToday() : from;
        if (to.isBefore(fromDate)) {
            throw new DelegationDatesException(fromDate, to);
        }
        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, user, by, fromDate, to));
        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + by + " user=" + user + " from="
                + saved.getFromDate() + " to=" + saved.getToDate());
        return saved;
    }
}
package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** The role a user name has on a sheet. */
@Entity
@Table(name = "sheet_role")
public class SheetRole {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    /** clerk, steward or viewer. */
    @Column(name = "role", nullable = false)
    private String role;

    protected SheetRole() {
    }

    public SheetRole(String sheetId, String userName, Role role) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role.value();
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUserName() {
        return userName;
    }

    public Role getRole() {
        return Role.of(role);
    }

    public void setRole(Role role) {
        this.role = role.value();
    }
}

